-- Bounded taxonomy correction; question/answer/legal evidence are preserved.
-- Newly identified legal questions without evidence are held under_review, never approved.
-- Includes 8 retained regional labels. Idempotent and atomic: abort on missing/changed stems.
CREATE TEMP TABLE taxonomy_review_755 (source_table text, id uuid, old_subject text, new_subject text, question_md5 text, quarantine boolean) ON COMMIT DROP;
DO $review$ DECLARE conflicts integer; BEGIN
SELECT count(*) INTO conflicts FROM taxonomy_review_755 r LEFT JOIN public.official_exam_questions q ON q.id=r.id WHERE r.source_table='official_exam_questions' AND (q.id IS NULL OR md5(q.question_text)<>r.question_md5 OR q.subject NOT IN (r.old_subject,r.new_subject));
IF conflicts<>0 THEN RAISE EXCEPTION 'Taxonomy snapshot conflict in official_exam_questions: %',conflicts; END IF;
UPDATE public.official_exam_questions q SET subject=r.new_subject, content_status=CASE WHEN r.quarantine AND q.content_status='active' THEN 'under_review' ELSE q.content_status END FROM taxonomy_review_755 r WHERE r.source_table='official_exam_questions' AND q.id=r.id AND (q.subject<>r.new_subject OR (r.quarantine AND q.content_status='active'));
SELECT count(*) INTO conflicts FROM taxonomy_review_755 r LEFT JOIN public.curated_question_catalog q ON q.id=r.id WHERE r.source_table='curated_question_catalog' AND (q.id IS NULL OR md5(q.question_text)<>r.question_md5 OR q.subject NOT IN (r.old_subject,r.new_subject));
IF conflicts<>0 THEN RAISE EXCEPTION 'Taxonomy snapshot conflict in curated_question_catalog: %',conflicts; END IF;
UPDATE public.curated_question_catalog q SET subject=r.new_subject, content_status=CASE WHEN r.quarantine AND q.content_status='active' THEN 'under_review' ELSE q.content_status END FROM taxonomy_review_755 r WHERE r.source_table='curated_question_catalog' AND q.id=r.id AND (q.subject<>r.new_subject OR (r.quarantine AND q.content_status='active'));
END $review$;
